      "skills_desc": "Az elektromos és automatizálási mérnöki alapok ötvözése az alkalmazott informatikával. Fókuszban az ipari vezérlőrendszerek és vállalati hálózatok biztonsága.",
      "edu_label": "Akadémiai Háttér",
      "edu_title": "Tanulmányok",
      "edu_desc": "A folyamatos tanulás szakmai filozófiám alapja. Az elektromos alapoktól a haladó kiberbiztonságig.",
      "edu1_deg": "BSc Alkalmazott Informatika - Kiberbiztonság Szakirány",
      "edu1_inst": "University of Applied Sciences West Flanders (HOWEST)",
      "edu1_period": "Szept 2023 - Jelenleg",
      "edu1_desc": "Releváns Kurzusok: Web- és Hálózati Behatolásvizsgálat, Digitális Törvényszék, Biztonsági Kockázatkezelés, Biztonságos Fejlesztés, Kiberbűnözés.",
      "edu2_deg": "Automatizálási Technikus: Ipari Automatizálás",
      "edu2_inst": "BGSZC Mechatronika Szakgimnázium",
      "edu2_period": "Jan 2017 - Jan 2022",
      "edu2_desc": "Átfogó képzés ipari automatizálási rendszerek, elektronika és mechanikai rendszerek terén.",
      "edu3_deg": "PLC Programozó: Automatizálási Technológia",
      "edu3_inst": "BGSZC Mechatronika Technikum",
      "edu3_period": "Jan 2020 - Jan 2021",
      "edu3_desc": "Speciális képesítés PLC programozás és automatizálási logika területén.",
      "lang_label": "Globális Kommunikáció",
      "lang_title": "Nyelvek",
